    .card__title {
      font-size: var(--text-small);
      font-weight: bold;
      min-block-size: 0;
    }
  }

  .card__notification-unread-indicator {
    --btn-background: var(--color-marker);
    --btn-border-color: var(--color-canvas);
    --btn-color: var(--color-ink-inverted);
    --btn-icon-size: 0.5em;
    --btn-padding: 0;
    --btn-size: 1.6em;

    font-size: var(--text-xx-small);
    font-weight: 600;
    margin: 2px;
    position: relative;
    z-index: 1;

    .icon {
      opacity: 0;
      transition: opacity 150ms ease;
    }

    @media (hover: hover) {
      .card:hover & {
        --btn-background: var(--color-ink-lightest);
        --btn-color: var(--color-ink);

        .badge-count { opacity: 0; }
               .icon { opacity: 1; }
      }
    }
  }

  .card__board-public-description {
    max-inline-size: 66ch;

    > *:first-child { margin-block-start: 0; }
    > *:last-child { margin-block-end: 0; }

    ul, ol {
      inline-size: fit-content;
      margin-inline: auto;
      text-align: start;
    }

    code {
      text-align: left;
    }
  }
